 1	import java.util.Arrays;
 2	
 3	public final class BubbleSort {
 4	
 5	    private BubbleSort() {
 6	        // Utility class.
 7	    }
 8	
 9	    public static void bubbleSort(int[] values) {
10	        validate(values);
11	        sortInPlace(values);
12	    }
13	
14	    public static int[] sortedCopy(int[] values) {
15	        validate(values);
16	
17	        int[] copy = Arrays.copyOf(values, values.length);
18	        sortInPlace(copy);
19	        return copy;
20	    }
21	
22	    private static int[] createDemoValues() {
23	        return new int[] { 64, 34, 25, 12, 22, 11, 90 };
24	    }
25	
26	    private static void validate(int[] values) {
27	        if (values == null) {
28	            throw new IllegalArgumentException("values must not be null");
29	        }
30	    }
31	
32	    private static void sortInPlace(int[] values) {
33	        int end = values.length - 1;
34	        while (end > 0) {
35	            int lastSwapIndex = bubblePass(values, end);
36	            if (lastSwapIndex == 0) {
37	                return;
38	            }
39	            end = lastSwapIndex - 1;
40	        }
41	    }
42	
43	    private static int bubblePass(int[] values, int endExclusive) {
44	        int lastSwapIndex = 0;
45	
46	        for (int index = 0; index < endExclusive; index++) {
47	            if (isOutOfOrder(values, index)) {
48	                swap(values, index, index + 1);
49	                lastSwapIndex = index + 1;
50	            }
51	        }
52	
53	        return lastSwapIndex;
54	    }
55	
56	    private static boolean isOutOfOrder(int[] values, int index) {
57	        return values[index] > values[index + 1];
58	    }
59	
60	    private static void swap(int[] values, int leftIndex, int rightIndex) {
61	        int temp = values[leftIndex];
62	        values[leftIndex] = values[rightIndex];
63	        values[rightIndex] = temp;
64	    }
65	
66	    private static String formatArray(int[] values) {
67	        StringBuilder builder = new StringBuilder();
68	
69	        for (int index = 0; index < values.length; index++) {
70	            if (index > 0) {
71	                builder.append(' ');
72	            }
73	            builder.append(values[index]);
74	        }
75	
76	        return builder.toString();
77	    }
78	
79	    private static void runDemo() {
80	        int[] values = createDemoValues();
81	        bubbleSort(values);
82	        System.out.println("Sorted array: ");
83	        System.out.println(formatArray(values));
84	    }
85	
